update sys_user_webauthn_credential
set status = '1',
    update_time = sysdate()
where user_id = #{userId}
  and credential_id = #{credentialId}
  and status = '0'

update sys_user_webauthn_credential
set credential_name = #{credentialName},
    update_time = sysdate()
where user_id = #{userId}
  and credential_id = #{credentialId}
  and status = '0'
